export const NETCDF_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/netcdf-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getNetcdfStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(NETCDF_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
